/* ============================================================================
   NORM — FY2025 Departmental account mapping (generated from the approved
   mapping workbook). Per-GL classification: statement line, note sub-line,
   account type and cash-flow class. FY-versioned; this is content, not code.
   Idempotent: table guard + seed guard on (FinancialYear, EntityCode).
   ============================================================================ */
SET NOCOUNT ON;

IF OBJECT_ID('dbo.tblNORM_AccountMap','U') IS NULL
CREATE TABLE dbo.tblNORM_AccountMap (
    AccountMapId    INT IDENTITY(1,1) PRIMARY KEY,
    FinancialYear   INT          NOT NULL,
    EntityCode      VARCHAR(20)  NOT NULL,
    GlCode          VARCHAR(20)  NOT NULL,
    GlDescription   VARCHAR(160) NULL,
    AccountType     VARCHAR(20)  NULL,   -- Income | Expense | Asset | Liability | Equity
    StatementLine   VARCHAR(80)  NULL,   -- maps to the statement-line template
    NoteSubLine     VARCHAR(120) NULL,   -- disclosure-note sub-line
    CashFlowClass   VARCHAR(80)  NULL,   -- direct-method cash-flow classification
    IsDeactivated   BIT          NOT NULL CONSTRAINT DF_NORM_AccMap_Deact DEFAULT(0)
);
IF NOT EXISTS (SELECT 1 FROM sys.indexes WHERE name='IX_NORM_AccMap_Lookup')
CREATE INDEX IX_NORM_AccMap_Lookup ON dbo.tblNORM_AccountMap(FinancialYear, EntityCode, GlCode);

IF NOT EXISTS (SELECT 1 FROM dbo.tblNORM_AccountMap WHERE FinancialYear=2025 AND EntityCode='DEPT')
